import {FEEDS, NETWORKS, addressMatches, fetchNewPools, fetchPublicSource, mergeArticles} from './public-radar.mjs';

const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>v===null||v===undefined?'—':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',notation:'compact',maximumFractionDigits:1}).format(v);
const num=v=>v===null||v===undefined?'—':Number(v).toLocaleString('en-US');
const age=time=>{const mins=Math.max(0,Math.round((Date.now()-time)/60000));return mins<60?`${mins}m old`:mins<1440?`${Math.floor(mins/60)}h old`:`${Math.floor(mins/1440)}d old`};
const state={hours:36,query:''},data={articles:[],coins:[],profiles:[]};let loading=false;

function qualified(c){return Number.isFinite(c.poolCreated)&&c.liquidity>=3000&&((c.buys??0)+(c.sells??0)>=5)}
function score(c){const fresh=Math.max(0,1-(Date.now()-c.poolCreated)/129600000)*45,liq=Math.min(20,Math.log10(Math.max(1,c.liquidity))*4),activity=Math.min(25,Math.log10(Math.max(1,(c.volume??0)+(c.buyers??0)*100))*5),buyers=Math.min(10,Math.log10(Math.max(1,c.buyers??0))*4);return fresh+liq+activity+buyers}
function candidates(){const q=state.query.trim().toLowerCase(),cutoff=Date.now()-state.hours*3600000;return data.coins.filter(c=>qualified(c)&&c.poolCreated>=cutoff&&(!q||`${c.name} ${c.symbol} ${c.contract_address}`.toLowerCase().includes(q))).sort((a,b)=>score(b)-score(a))}
function same(a,b){return String(a??'').toLowerCase()===String(b??'').toLowerCase()}
const ignoredWords=new Set('coin coins token tokens crypto market meme official the and for with from this that new launch launched'.split(' '));
function words(value){return [...new Set(String(value??'').toLowerCase().replace(/[^a-z0-9 ]/g,' ').split(/\s+/).filter(word=>word.length>=4&&!ignoredWords.has(word)))]}
function relatedNews(c){const text=article=>`${article.title} ${article.summary}`.toLowerCase(),name=String(c.name||'').trim().toLowerCase(),symbol=String(c.symbol||'').trim().toLowerCase(),terms=words(c.name);return data.articles.filter(article=>{const body=text(article);if(name.length>=4&&body.includes(name))return true;if(symbol.length>=4&&new RegExp(`(^|[^a-z0-9])\\$?${symbol.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}([^a-z0-9]|$)`,'i').test(body))return true;return terms.length>=2&&terms.filter(term=>body.includes(term)).length>=2}).slice(0,2)}
function profileLead(c){const usable=p=>p&&(p.description?.trim()||p.links?.some(link=>/x\.com|twitter\.com/i.test(link.url||'')));const exact=data.profiles.find(p=>same(p.tokenAddress,c.contract_address));if(exact)return {kind:'verified',profile:exact};const match=data.profiles.filter(p=>usable(p)&&(same(p.name,c.name)||same(p.symbol,c.symbol))).sort((a,b)=>(same(b.chainId,c.network)?1:0)-(same(a.chainId,c.network)?1:0))[0];return match?{kind:'possible',profile:match}:null}
function context(c){const articles=data.articles.filter(a=>addressMatches({posts:[a]},[c]).length);if(articles.length)return {kind:'verified',articles};const profile=profileLead(c);if(profile?.kind==='verified')return profile;const news=relatedNews(c);return news.length?{kind:'rss',articles:news}:profile}
function profileLinks(profile){return (profile.links||[]).filter(l=>/^https:\/\//.test(l.url||'')).slice(0,2).map(l=>`<a href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">${esc(l.type==='twitter'?'Open X evidence':l.label||'Open source')} ↗</a>`).join('')}
function explanation(found,c){if(found?.articles){const exact=found.kind==='verified';return `<div class="story-answer ${exact?'':'possible'}"><span>What it is</span><p>${exact?'Public coverage contains this exact contract.':'This article overlaps the coin name or ticker. It is a narrative lead, not proof that the article refers to this contract.'}</p></div><div class="evidence-links">${found.articles.slice(0,2).map(p=>`<a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">${esc(p.publisher)} · ${esc(p.title)} ↗</a>`).join('')}</div>`}if(found?.profile){const profile=found.profile,possible=found.kind==='possible',description=profile.description?.trim()||'This token profile links to an X source but has no written description.';return `<div class="story-answer ${possible?'possible':''}"><span>What it is</span><p>${esc(description)}${possible?` This is a ${esc(profile.chainId||'different-chain')} name/ticker lead, so it is not proof that this pool is official.`:''}</p></div><div class="evidence-links">${profileLinks(profile)}</div>`}const query=encodeURIComponent(`"${c.contract_address}" OR "$${c.symbol}" OR "${c.name}"`);return `<div class="story-answer pending"><span>What it is</span><p>Context pending. The new-pool feed identifies this contract, but the connected sources do not yet explain the name, meme, person, or event behind it.</p></div><div class="evidence-links"><a href="https://x.com/search?q=${query}&src=typed_query&f=live" target="_blank" rel="noopener noreferrer">Search X for this coin ↗</a></div>`}
function card(c,found,index){const kind=found?.kind||'pending',label=kind==='verified'?'Verified evidence':kind==='rss'?'Related RSS lead':kind==='possible'?'Possible context':'Context pending';return `<article class="new-coin-card"><div class="coin-head"><span class="rank">${String(index+1).padStart(2,'0')}</span><div><h3>$${esc(c.symbol)}</h3><small>${esc(c.name)} · ${esc(c.chain)} · ${esc(age(c.poolCreated))}</small></div><span class="context-state ${kind==='rss'?'possible':kind}">${label}</span></div>${explanation(found,c)}<dl class="new-metrics"><div><dt>Liquidity</dt><dd>${money(c.liquidity)}</dd></div><div><dt>24H volume</dt><dd>${money(c.volume)}</dd></div><div><dt>Pool buyers</dt><dd>${num(c.buyers)}</dd></div></dl><div class="coin-footer"><code title="${esc(c.contract_address)}">${esc(c.contract_address)}</code><a class="text-button" href="./?query=${encodeURIComponent(c.contract_address)}">Research ↗</a></div></article>`}
function render(){const rows=candidates(),explained=rows.filter(c=>context(c)),pending=rows.filter(c=>!context(c));$('#explained-count').textContent=explained.length;$('#pending-count').textContent=pending.length;$('#explained').innerHTML=explained.length?explained.map((c,i)=>card(c,context(c),i)).join(''):'<div class="new-empty"><strong>No supported story matches yet.</strong>DEX profile descriptions, linked X posts, and exact contract evidence will appear here when available.</div>';$('#pending').innerHTML=pending.length?pending.slice(0,30).map((c,i)=>card(c,null,i)).join(''):'<div class="new-empty"><strong>No qualified new pools in this window.</strong>Try 36H or refresh the discovery feeds.</div>';$('#status').textContent=loading?'Refreshing discovery and context feeds…':`${rows.length} qualified new-pool candidates · ${state.hours}H window · Solana + Base · context: public profiles, linked X posts, and news`}
async function fetchProfiles(){const response=await fetch('https://api.dexscreener.com/token-profiles/latest/v1',{signal:AbortSignal.timeout(15000)});if(!response.ok)throw new Error('Profile feed unavailable.');const profiles=await response.json();if(!Array.isArray(profiles))return [];const groups=new Map();for(const profile of profiles){if(profile.chainId&&profile.tokenAddress){const list=groups.get(profile.chainId)||[];list.push(profile.tokenAddress);groups.set(profile.chainId,list)}}const metadata=await Promise.allSettled([...groups].map(async([chain,addresses])=>{const response=await fetch(`https://api.dexscreener.com/tokens/v1/${encodeURIComponent(chain)}/${addresses.slice(0,30).map(encodeURIComponent).join(',')}`,{signal:AbortSignal.timeout(15000)});return response.ok?await response.json():[]}));const byAddress=new Map();for(const result of metadata)if(result.status==='fulfilled'&&Array.isArray(result.value))for(const pair of result.value){for(const token of [pair.baseToken,pair.quoteToken])if(token?.address)byAddress.set(String(token.address).toLowerCase(),token)}return profiles.map(profile=>({...profile,...(byAddress.get(String(profile.tokenAddress).toLowerCase())||{})}))}
async function refresh(){if(loading)return;loading=true;render();const results=await Promise.allSettled([...NETWORKS.map(n=>fetchNewPools(n)),...FEEDS.map(f=>fetchPublicSource(f)),fetchProfiles()]);data.coins=[];data.articles=[];data.profiles=[];results.slice(0,NETWORKS.length).forEach(r=>{if(r.status==='fulfilled')data.coins.push(...r.value)});results.slice(NETWORKS.length,NETWORKS.length+FEEDS.length).forEach(r=>{if(r.status==='fulfilled')data.articles=mergeArticles(data.articles,r.value)});const profiles=results.at(-1);if(profiles.status==='fulfilled')data.profiles=profiles.value;loading=false;render()}
document.addEventListener('click',event=>{const button=event.target.closest('[data-hours]');if(!button)return;state.hours=Number(button.dataset.hours);document.querySelectorAll('[data-hours]').forEach(x=>x.setAttribute('aria-pressed',String(x===button)));render()});
$('#query').addEventListener('input',event=>{state.query=event.target.value;render()});$('#refresh').addEventListener('click',refresh);render();refresh();
